// ---- POD reads under SEH (no C++ objects with destructors inside a __try - C2712) ----
// PROBE-START: P120 (M7a A1 P-b, 2026-10-02) - writer member order/handles vs the other game's load of the same record
/* For A2: does a squad record loaded on the OTHER game keep the writer's member order and handles? The writer logs, for a record it
   WROTE, its members in the active list's order (uid, handle index.serial) read just before the sleep; the loader logs the same for a
   squad woken here from a record another slot wrote. Join the two logs by wid. Log only, POD reads under SEH, the first 40 each side. */
struct P120Member { unsigned int uid, idx, serial; char sid[48]; };   /* fold 1 [a1b1f1-st0] [F6]: + the member's GameData stringID ("?" unread) */
static P120Member g_p120Mem[64]; static int g_p120N = -1;
static long long g_p120Writes = 0, g_p120Loads = 0;
static void* g_p120LoadPlatoon = 0; static int g_p120LoadWriter = -1;
static int g_p120Path = 0; static std::map<void*, int> g_p120Created;   /* [F6]: path 1 = a squad CreateUnknownSquad built (platoon -> writer slot until its first wake) */
static int P120MemberPtrs(void** members, int n, void** out, int cap)   /* no C++ object in here (C2712) */
{
    __try { int k = 0; for (; k < n && k < cap; ++k) out[k] = members[k]; return k; }
    __except (EXCEPTION_EXECUTE_HANDLER) { return -1; }
}
static int P120MemberSid(void* ch, char* out, int cap)   /* [F6] POD under SEH (C2712): 1 = read */
{
    out[0] = 0;
    __try { const void* gd = ((::Character*)ch)->getRecordDirect(); return gd != 0 ? GameDataSidPod(gd, out, cap) : 0; }
    __except (EXCEPTION_EXECUTE_HANDLER) { out[0] = 0; return 0; }
}
static int P120Read(void** members, int activeChars, P120Member* out, int cap)
{
    void* ptrs[64];
    const int n = (members != 0 && activeChars > 0) ? P120MemberPtrs(members, activeChars, ptrs, cap < 64 ? cap : 64) : 0;
    for (int k = 0; k < n; ++k)
    {
        ObjId id; std::memset(&id, 0, sizeof(id));
        out[k].uid = Plaus(ptrs[k]) ? FindSpawnedUid(ptrs[k]) : 0u;
        if (Plaus(ptrs[k]) && CaptureObjId(ptrs[k], &id)) { out[k].idx = id.index; out[k].serial = id.serial; } else { out[k].idx = 0; out[k].serial = 0; }
        out[k].sid[0] = 0; if (Plaus(ptrs[k]) && P120MemberSid(ptrs[k], out[k].sid, (int)sizeof(out[k].sid)) != 1) out[k].sid[0] = 0;
    }
    return n;
}
static std::string P120List(const P120Member* m, int n)
{
    std::string s;
    for (int k = 0; k < n; ++k) s += " [" + N((long long)k) + ":" + N((long long)m[k].uid) + ":" + N((long long)m[k].idx) + "." + N((long long)m[k].serial) + ":" + std::string(m[k].sid[0] != 0 ? m[k].sid : "?") + "]";
    return s;
}
