struct StateScan { int member; int n1E; int nRec; void* first1E; };
/* 1 = walked, 0 = more nodes than the count (a broken container), -1 = the walk faulted. */
int StateScanPod(void* container, const void* rec, StateScan* o)
{
    o->member = 0; o->n1E = 0; o->nRec = 0; o->first1E = 0;
    __try
    {
        const char* c = (const char*)container;
        const unsigned long long cnt = *(const unsigned long long*)(c + 0xF0);
        const char* node = 0;
        if (cnt != 0) node = *(const char* const*)(*(const char* const*)(c + 0x108) + *(const long long*)(c + 0xE8) * 8);
        unsigned long long walked = 0;
        for (; node != 0; node = *(const char* const*)node)
        {
            if (++walked > cnt) return 0;
            const char* r = *(const char* const*)(node + 0x38);
            if (r == 0) continue;
            ++o->nRec;
            if ((const void*)r == rec) o->member = 1;
            if (*(const int*)(r + 0x50) == 0x1E) { if (o->n1E == 0) o->first1E = (void*)r; ++o->n1E; }
        }
        return 1;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { return -1; }
}
