// ---- files ----
std::string Sanitize(const std::string& s)
{
    std::string o; for (size_t i = 0; i < s.size(); ++i) { char c = s[i]; o += (isalnum((unsigned char)c) || c == '-' || c == '_' || c == '.') ? c : '_'; }
    return o;
}
/* P7b - THE SAVE ROOT, IN ONE PLACE. The notebook's folder has always been derived from it ("coop-store" sits
   BESIDE the slots, decision 22), and P7b needs the same root to find a slot folder when the engine's own folder
   argument cannot be used (see SlotDirFor). Confirmed on disk in read-e39 section 1: this directory is what holds s1,
   s2, autosave0/1/2 and coop-store. Both instances of this project run as the same Windows user, so both resolve
   the same root and are told apart by their slot, which is exactly what the config file's `slot=` names. */
/* P8J-B2 (bench 2, F738): shared_wastelands.cfg's saveroot= replaces the whole answer when present (ConfigSaveRoot, already
   checked absolute and stripped of trailing separators by coopcfg::CfgRootPathOk). saveroot= is a TEST-ONLY key (the harness points a
   game at its own folders with it); absent = the engine's own folder below (T-220 item 7). */
/* T-220 item 7 (owner 179; F718, F719): THE ENGINE'S OWN SAVE FOLDER. SaveManager::getSavePath (0x47A120 in 1.0.65) is nineteen bytes
   that return &this+0x78 or &this+0x50 on settings.cfg's "User save location" byte - the table row's bytes include that compare, so a
   verified row is the engine's own choice, never a copy of it. Asked only once the title screen has been up (initialisePaths runs from
   WinMain before it; getSingleton would CONSTRUCT an unpathed SaveManager earlier, F719), and an empty answer is no answer. */
static unsigned long long kSmGetSavePath = 0; static coop::AddrReg kSmGetSavePath_reg("SaveManager_saveFolder", &kSmGetSavePath);   /* Steam_1.0.65 0x47A120 */
int TitleScreenUpPod();   /* defined below, beside the pump gate */
static int EngineSavePathPod(void* sm, char* buf, int cap)
{
    const unsigned long long a = coop::AddrAbs(kSmGetSavePath);
    if (a == 0 || sm == 0) return 0;
    const void* s = 0;
    __try { typedef const void* (*Fn)(void* self); s = ((Fn)a)(sm); }
    __except (EXCEPTION_EXECUTE_HANDLER) { return 0; }
    return (s != 0 && CopyStdStringPod(s, buf, cap)) ? 1 : 0;
}
static int g_saveRootEngineSeen = 0;   /* the title screen has been up once: the engine's paths are set */
static std::string g_saveRootSaid;     /* the last answer logged - a change is logged once */
std::string SaveRootDefault()
{
    const std::string cfgRoot = ConfigSaveRoot();
    if (!cfgRoot.empty()) return cfgRoot;
    if (g_saveRootEngineSeen == 0 && (TitleScreenUpPod() == 1 || coop::GameplayRunning())) g_saveRootEngineSeen = 1;
    std::string root, from = "the engine (SaveManager::getSavePath)";
    char b[1024]; b[0] = 0;
    if (g_saveRootEngineSeen != 0 && EngineSavePathPod(OwnSaveManagerPtr(), b, (int)sizeof(b)) == 1)
    {
        b[sizeof(b) - 1] = 0;
        root = b;
        while (!root.empty() && (root[root.size() - 1] == '\\' || root[root.size() - 1] == '/')) root.erase(root.size() - 1);
        const bool absolute = root.size() >= 3 && root[1] == ':' && (root[2] == '\\' || root[2] == '/');
        if (!root.empty() && !absolute)   /* the game-folder choice may be relative to Kenshi's own folder (its working directory) */
        {
            char full[1024]; full[0] = 0;
            const DWORD n = U8GetFullPathName(root.c_str(), (DWORD)sizeof(full), full, 0);
            root = (n > 0 && n < sizeof(full)) ? std::string(full) : std::string();
        }
    }
    if (root.empty())   /* before the engine can answer: the rule this build had before T-220, said as such in the log */
    {
        const std::string la = U8GetEnv("LOCALAPPDATA");   /* UTF-8, as the engine's own save folder is */
        if (!la.empty()) root = la + "\\kenshi\\save";   /* owner 244: no developer folder when it is unset */
        from = g_saveRootEngineSeen != 0 ? "LOCALAPPDATA - the engine gave no save folder (row missing, or its string empty or unreadable)"
                                         : "LOCALAPPDATA - the title screen has not been up yet, so the engine is not asked";
    }
    static bool s_noRootSaid = false;
    if (root.empty() && !s_noRootSaid)
    {
        s_noRootSaid = true;
        ErrorLog("[SAVE] no save folder: the engine gave none and LOCALAPPDATA is not set - no folder is made up; what needs one is refused");
    }
    if (root != g_saveRootSaid)
    {
        g_saveRootSaid = root;
        if (from.compare(0, 10, "the engine") == 0 || g_saveRootEngineSeen == 0) DebugLog("[SAVE] T-220: save folder '" + root + "' from " + from);
        else ErrorLog("[SAVE] T-220: save folder '" + root + "' from " + from);
    }
    return root;
}
/* P8J-B2: THE NOTEBOOK'S TOP FOLDER - storedir= when present, else <data folder>\\worlds, else <save root>\\Shared Wastelands\\worlds (owner 244), else "" (refused). Every world's
   folder is made inside it (SetStoreDirsFor, StoreNotebookDir: coopworld::WorldDirIn). */
std::string BaseDir()
{
    const std::string cfgStore = ConfigStoreDir();
    if (!cfgStore.empty()) return cfgStore;
    /* PP3 (manager 2026-09-27): the notebook's data lives in <data folder>\\worlds, OUT of Kenshi's save folder, so Kenshi's
       LOAD GAME never lists it. No usable data folder = <save root>\\Shared Wastelands\\worlds; no save root either = "". */
    const std::string worlds = coopdata::WorldsDir(ConfigDataDir());
    if (!worlds.empty()) return worlds;
    const std::string saveRoot = SaveRootDefault();
    return saveRoot.empty() ? std::string() : saveRoot + "\\" + swnames::kSaveRootSub + "\\worlds";
}
/* tickwait (bench 2): EVERY MISSING LEVEL, not just the last. One _mkdir made the mirror folder only when its parent
   already existed, so under a store folder that did not (a fresh storedir=, a new world) every heartbeat and zone write
   failed. Fast path unchanged: one _mkdir, done when it made the folder or the folder is there; only a failure for
   another reason (a missing parent) walks the levels (coopdir::DirLevels), shortest first. */
void EnsureDir(const std::string& d)
{
    if (d.empty()) return;
    if (U8Mkdir(d.c_str()) == 0 || errno == EEXIST) return;
    std::vector<std::string> levels;
    coopdir::DirLevels(d, &levels);
    for (size_t i = 0; i < levels.size(); ++i) U8Mkdir(levels[i].c_str());
}
/* P7i (T233 section 5) - THE NOTEBOOK'S TWO FOLDERS, MADE ONLY FOR A CO-OP WORLD, IN ONE PLACE.
   Both `EnsureDir` calls used to run unconditionally at hook-install time, above the RoleIsSingle() test, so a
   lone game created `coop-store\` and an empty `coop-store\mirror-<pid>\` before the role was ever consulted.
   T233 found exactly that: one empty mirror directory, no files anywhere. Harmless, and still wrong by decision
   43 - a lone game must leave no trace of a co-op world. They move into the co-op arm, and into ONE function
   with ONE caller since W2b, StoreArmWorldIndex (reached from the install's own else-branch, from StoreRoleLeftSingle
   when a verb turns a lone game into a co-op one, and from the notebook's store WELCOME), because "create the folders" and "read the index" must happen together or not at all. */
void EnsureStoreDirs() { EnsureDir(g_dirCanonical); EnsureDir(g_dirMirror); }
/* W2b (decision 58; design-worlds section 1) - THE ONE SETTER OF THE NOTEBOOK FOLDER NAMES, FOR ONE WORLD.
   coop-store\<world folder> holds that world's records; this process's mirror sits inside it. An empty or invalid
   name is the default world coopworld::kDefaultWorld (coopworld::WorldDir), the same fallback the notebook uses. Names only - no
   folder is created here (EnsureStoreDirs does that, beside the index read). */
std::string StoreDataDirFor(const std::string& world, const std::string& worldId, bool* joined, std::string* ownDir, bool* fellBack);   /* T-490: below, beside StoreArmWorldIndex */
void SetStoreDirsFor(const std::string& world, const std::string& worldId = std::string())   /* T-490: worldId = the link's ("" = none: the world's own folder) */
{
    bool fellBack = false, joined = false;
    g_dirCanonical = StoreDataDirFor(world, worldId, &joined, 0, &fellBack);   /* P8J-B2: = WorldDir(SaveRootDefault(), ...) when storedir= is absent; T-490: a joined world's own folder */
    g_dirJoined = joined;
    g_dirWorld = coopworld::WorldFolderName(coopworld::WorldOrDefault(world, 0));
    { std::ostringstream o; o.imbue(std::locale::classic()); o << g_dirCanonical << "\\mirror-" << ::GetCurrentProcessId(); g_dirMirror = o.str(); }
    if (fellBack && !world.empty())
        DebugLog("[STORE] W2b: the world name '" + world + "' cannot be a folder name, so this game uses world '" + g_dirWorld + "'s folder " + g_dirCanonical + ".");
    if (joined)
        DebugLog("[STORE] T-490: world '" + world + "' (id " + worldId + ") is joined, not run on this computer - its queue and mirror are kept in "
                 + g_dirCanonical + ", apart from any world of that name this computer runs.");
}
bool IsZoneId(const std::string& worldId) { return worldId.compare(0, 5, "zone.") == 0; }   // P3 piece 3: "zone.<X>.<Y>"
/* the data file the world server writes in its own folder: <id>.platoon for every record, area records included */
std::string CanonicalFile(const std::string& worldId) { return recname::ServerDataFile(g_dirCanonical, Sanitize(worldId)); }
std::string MetaFile(const std::string& worldId) { return g_dirCanonical + "\\" + Sanitize(worldId) + ".meta"; }
std::string MirrorFile(const std::string& worldId) { return recname::MirrorDataFile(g_dirMirror, Sanitize(worldId), IsZoneId(worldId)); }
/* Z1-b (review-z1 item 1): MAIN THREAD. Copy g_records' current entry for one zone id into the swap table, or remove it.
   Called after every g_records write or erase that can touch a zone id; a non-zone id returns at once. */
void ZoneSwapPublish(const std::string& worldId)
{
    if (!IsZoneId(worldId)) return;
    PendingLockInit();   /* the main thread; normally already done at install */
    std::map<std::string, Record>::const_iterator it = g_records.find(worldId);
    ::EnterCriticalSection(&g_zoneSwapLock);
    if (it == g_records.end()) g_zoneSwapTS.erase(worldId);
    else { ZoneSwapEntry& e = g_zoneSwapTS[worldId]; e.file = it->second.file; e.owner = it->second.owner; e.writtenAt = it->second.writtenAt; e.seq = it->second.seq; }
    ::LeaveCriticalSection(&g_zoneSwapLock);
    if (it == g_records.end() || it->second.file.empty()) { g_areaNamed.erase(worldId); g_areaScanQueue.erase(worldId); }
    else if (g_areaScanQueue.size() < 65536) g_areaScanQueue.insert(worldId);   /* AreaOwnerScanTick reads which players its file names */
    ++g_zoneSwapPubGen;   /* AreaWriterStandInsTick looks at the table again */
}
/* Any thread: copy one entry out. */
bool ZoneSwapLookup(const std::string& zoneId, ZoneSwapEntry* out)
{
    if (!g_zoneSwapLockInit) return false;
    bool found = false;
    ::EnterCriticalSection(&g_zoneSwapLock);
    std::map<std::string, ZoneSwapEntry>::const_iterator it = g_zoneSwapTS.find(zoneId);
    if (it != g_zoneSwapTS.end()) { *out = it->second; found = true; }
    ::LeaveCriticalSection(&g_zoneSwapLock);
    return found;
}
/* MAIN THREAD: apply what the detours learned, per zone, last event wins. Every reader of g_zoneFromRecord calls it first. */
void ZoneFromRecordDrain()
{
    if (!g_zoneSwapLockInit || !OnMainThread()) return;
    std::map<std::string, ZoneMarkEvent> ev; bool clearReq = false;
    ::EnterCriticalSection(&g_zoneSwapLock);
    ev.swap(g_zoneMarkPending);
    clearReq = g_zoneMarksClearReq; g_zoneMarksClearReq = false;   /* Z1-c (recheck-z1b item 1): taken with the events, in one hold */
    ::LeaveCriticalSection(&g_zoneSwapLock);
    /* Z1-c: an off-main world teardown asked for the map to go (TeardownBroadcastLateFlags). It is counted and cleared
       here, BEFORE the events swapped out above - they were queued after that teardown, so they describe the new world. */
    if (clearReq) { ::InterlockedExchangeAdd(&g_teardownLateMarks, (long)g_zoneFromRecord.size()); g_zoneFromRecord.clear(); }
    for (std::map<std::string, ZoneMarkEvent>::const_iterator it = ev.begin(); it != ev.end(); ++it)
    {
        if (it->second.loaded) g_zoneFromRecord[it->first] = it->second.stamp; else g_zoneFromRecord.erase(it->first);
    }
}
/* Any thread: a zone read (loaded=false) or a load from a record (loaded=true). On the main thread the pending events are
   drained first and the mark is applied directly - the old behaviour; off it, the event is queued for the drain. */
void ZoneMarkNote(const std::string& zoneId, bool loaded, const ZoneStamp& stamp)
{
    if (OnMainThread())
    {
        ZoneFromRecordDrain();
        if (loaded) g_zoneFromRecord[zoneId] = stamp; else g_zoneFromRecord.erase(zoneId);
        return;
    }
    if (!g_zoneSwapLockInit) return;
    ::EnterCriticalSection(&g_zoneSwapLock);
    ZoneMarkEvent& e = g_zoneMarkPending[zoneId]; e.loaded = loaded; e.stamp = stamp;
    ::LeaveCriticalSection(&g_zoneSwapLock);
}
/* Any thread: the readFile -> load handshake (see g_zonePendingByPath). */
void ZonePendingDropZone(const std::string& zoneId)
{
    if (!g_zoneSwapLockInit || ::InterlockedCompareExchange(&g_zonePendingCount, 0, 0) == 0) return;
    ::EnterCriticalSection(&g_zoneSwapLock);
    for (std::map<std::string, ZonePendingLoad>::iterator it = g_zonePendingByPath.begin(); it != g_zonePendingByPath.end(); )
    {
        if (it->second.zoneId == zoneId) g_zonePendingByPath.erase(it++); else ++it;
    }
    ::InterlockedExchange(&g_zonePendingCount, (LONG)g_zonePendingByPath.size());
    ::LeaveCriticalSection(&g_zoneSwapLock);
}
/* Z1-c (recheck-z1b item 2): the handshake is set only while the swap entry is still the one the worker looked up (`seen`),
   checked in the same hold of g_zoneSwapLock. The main thread hides the entry in that lock before it rewrites a mirror
   file (ZoneSwapHideUnlessLoading), so a load is either visible to that writer - which then waits - or not served at
   all. Answers false (no handshake; the caller serves the engine's own copy) when the entry is gone or changed. */
bool ZonePendingSet(const std::string& path, const ZonePendingLoad& p, const ZoneSwapEntry& seen)
{
    if (!g_zoneSwapLockInit) return false;
    bool set = false;
    ::EnterCriticalSection(&g_zoneSwapLock);
    std::map<std::string, ZoneSwapEntry>::const_iterator it = g_zoneSwapTS.find(p.zoneId);
    if (it != g_zoneSwapTS.end() && it->second.file == seen.file && it->second.owner == seen.owner && it->second.writtenAt == seen.writtenAt && it->second.seq == seen.seq)
    { g_zonePendingByPath[path] = p; set = true; }
    ::InterlockedExchange(&g_zonePendingCount, (LONG)g_zonePendingByPath.size());
    ::LeaveCriticalSection(&g_zoneSwapLock);
    return set;
}
bool ZonePendingTake(const std::string& path, ZonePendingLoad* out)
{
    if (!g_zoneSwapLockInit) return false;
    bool found = false;
    ::EnterCriticalSection(&g_zoneSwapLock);
    std::map<std::string, ZonePendingLoad>::iterator it = g_zonePendingByPath.find(path);
    if (it != g_zonePendingByPath.end()) { *out = it->second; g_zonePendingByPath.erase(it); found = true; }
    ::InterlockedExchange(&g_zonePendingCount, (LONG)g_zonePendingByPath.size());
    ::LeaveCriticalSection(&g_zoneSwapLock);
    return found;
}
/* Z1-b (review-z1 item 4): is the copy loaded from `loaded` older than the record now held? writtenAt first (whole
   seconds); inside one second the notebook's seq decides, and only when the loaded stamp HAS one - a stamp this game
   took from its own write carries seq 0 and the notebook's later restamp of that same record must not read as newer. */
/* Z1-b: MAIN THREAD. Take one zone out of the swap table while its mirror file is being rewritten, so no worker serves
   new bytes under the previous record's owner and stamp; the caller republishes (ZoneSwapPublish) on every exit after. */
void ZoneSwapHide(const std::string& zoneId)
{
    if (!g_zoneSwapLockInit) return;
    ::EnterCriticalSection(&g_zoneSwapLock);
    g_zoneSwapTS.erase(zoneId);
    ::LeaveCriticalSection(&g_zoneSwapLock);
}
/* Z1-c (recheck-z1b item 2): MAIN THREAD. ZoneSwapHide unless a worker's load of `path` is in flight (its handshake entry
   is in g_zonePendingByPath) - then nothing is hidden and the answer is false, and the caller must not write the file.
   One hold of the lock, so no worker can set a handshake for this path between the test and the hide (ZonePendingSet). */
bool ZoneSwapHideUnlessLoading(const std::string& zoneId, const std::string& path)
{
    if (!g_zoneSwapLockInit) return true;
    bool freeToWrite = true;
    ::EnterCriticalSection(&g_zoneSwapLock);
    if (g_zonePendingByPath.find(path) != g_zonePendingByPath.end()) freeToWrite = false; else g_zoneSwapTS.erase(zoneId);
    ::LeaveCriticalSection(&g_zoneSwapLock);
    return freeToWrite;
}
/* Z1-b: any thread (the world teardown). Drops the readFile -> load handshakes, and with marksToo the undrained load
   facts with the world they describe (only in TeardownBroadcastLateFlags, where E33 clears g_zoneFromRecord - the
   post-teardown flush has to see them); answers how many were "loaded from a record" marks, so the marks count keeps them. */
long ZoneMarkPendingClear(bool marksToo, bool requestMapClear)
{
    if (!g_zoneSwapLockInit) return 0;
    long marks = 0;
    ::EnterCriticalSection(&g_zoneSwapLock);
    if (marksToo)
    {
        for (std::map<std::string, ZoneMarkEvent>::const_iterator it = g_zoneMarkPending.begin(); it != g_zoneMarkPending.end(); ++it) if (it->second.loaded) ++marks;
        g_zoneMarkPending.clear();
    }
    /* Z1-c (recheck-z1b item 1): requestMapClear (an off-main teardown): the late count is set to the undrained marks HERE,
       inside the lock and before the request, so the drain's add of the map's size cannot land first and be overwritten.
       A main-thread teardown (marksToo alone) clears the map itself, which answers any earlier request too. */
    if (requestMapClear) { ::InterlockedExchange(&g_teardownLateMarks, marks); g_zoneMarksClearReq = true; }
    else if (marksToo) g_zoneMarksClearReq = false;
    g_zonePendingByPath.clear(); ::InterlockedExchange(&g_zonePendingCount, 0);
    ::LeaveCriticalSection(&g_zoneSwapLock);
    return marks;
}
bool ZoneLoadedCopyOlder(const ZoneStamp& loaded, const Record& cur)
{
    if (cur.writtenAt != loaded.writtenAt) return cur.writtenAt > loaded.writtenAt;
    return loaded.seq != 0 && cur.seq > loaded.seq;
}
bool ReadFileBytes(const std::string& path, std::vector<char>* out);
/* MAIN THREAD: the player numbers area record `zoneId` (its swap entry `sw`) names as building owners, and whether it names a
   protocol-67 "coop-peer" owner (*legacy, may be null) - read from its file once per record version and kept in g_areaNamed.
   1 = *slots filled, 0 = the file could not be read (counted). */
int AreaNamedSlotsOf(const std::string& zoneId, const ZoneSwapEntry& sw, std::vector<int>* slots, bool* legacy = 0)
{
    std::map<std::string, AreaNamed>::iterator c = g_areaNamed.find(zoneId);
    if (c != g_areaNamed.end() && c->second.writtenAt == sw.writtenAt && c->second.seq == sw.seq) { *slots = c->second.slots; if (legacy) *legacy = c->second.legacy; return 1; }
    std::vector<char> b;
    if (sw.file.empty() || !ReadFileBytes(sw.file, &b)) { ++g_areaScanReadFail; return 0; }
    ++g_areaScans;
    std::vector<int> named; bool leg = false;
    if (!b.empty()) coopslot::ZoneFileNamedSlots((const unsigned char*)&b[0], b.size(), &named, &leg);
    AreaNamed& e = g_areaNamed[zoneId];
    if (e.slots != named) ++g_areaNamedGen;
    e.writtenAt = sw.writtenAt; e.seq = sw.seq; e.slots = named; e.legacy = leg;
    *slots = named;
    if (legacy) *legacy = leg;
    return 1;
}
bool ReadFileBytes(const std::string& path, std::vector<char>* out)
{
    std::ifstream f(U8W(path.c_str()).c_str(), std::ios::binary); if (!f) return false;
    f.seekg(0, std::ios::end); std::streamoff n = f.tellg(); f.seekg(0);
    if (n < 0 || n > (64 << 20)) return false;
    out->resize((size_t)n); if (n) f.read(&(*out)[0], n);
    return (bool)f;
}
/* flush = true: the bytes reach the disk before the rename - only for the small identity files written whole by rename (world.txt,
   format.txt, multiplayer-world.key), never for records, mirrors, heartbeats or the queue, which are written often. */
bool WriteFileBytes(const std::string& path, const std::vector<char>& b, bool flush = false)
{
    /* P7i (T233 section 5). THE WRITE MAKES ITS OWN FOLDER. Until P7i every writer below could assume the two store
       folders existed, because they were created unconditionally at hook-install time. A lone game now creates
       neither, and `zonestate on` is a reachable verb that turns a writer on in one - so the assumption has to
       stop being an assumption. One _mkdir of the path's own parent, at the single choke point every store
       write goes through, rather than a creation kept in step by hand with each writer (lesson 11). _mkdir on a
       directory that already exists is a no-op returning EEXIST, and this is also correct for the save-slot
       writes at SlotDirFor, which make their own folder a line before calling here. */
    const std::string::size_type pdir = path.find_last_of("\\/");
    if (pdir != std::string::npos && pdir > 0) EnsureDir(path.substr(0, pdir));
    /* B10 (audit C8) - THE TRIPWIRE. Every byte this plugin writes to a file goes through here. After
       C8 there is no code path left that can name a canonical record file: both assignments of
       Record::file say MirrorFile() unconditionally and WriteMeta is gone. This refuses one anyway
       and books it, so "C8 is really gone" is a number rather than an argument. */
    if (StoreCanonicalRecordPath(path)) { ++g_canonWriteAttempted; return false; }
    // review-p3a S5: the store folder is shared by both games on this PC; a truncate-in-place write can be read half-written.
    char sfx[32]; std::sprintf(sfx, ".%lu.tmp", (unsigned long)::GetCurrentProcessId());
    const std::string tmp = path + sfx;   // review-p3h H5: unique per process, so two writers never share a temp file
    {   /* written whole to a temp file (flushed to the disk first when asked), then renamed over the old one */
        HANDLE h = U8CreateFile(tmp.c_str(), GENERIC_WRITE, 0, 0, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, 0);
        if (h == INVALID_HANDLE_VALUE) return false;
        DWORD put = 0;
        const bool ok = (b.empty() || (::WriteFile(h, &b[0], (DWORD)b.size(), &put, 0) != 0 && put == (DWORD)b.size())) && (!flush || ::FlushFileBuffers(h) != 0);
        ::CloseHandle(h);
        if (!ok) { U8DeleteFile(tmp.c_str()); return false; }
    }
    if (U8MoveFileEx(tmp.c_str(), path.c_str(), MOVEFILE_REPLACE_EXISTING) != 0) return true;
    U8DeleteFile(tmp.c_str());
    return false;
}
/* B10 (audit C8): WriteMeta IS DELETED. It wrote a v4 line into the notebook's folder from the game,
   which is the notebook's job and the notebook's format (v6 now, with a length and a checksum this
   side never computed). Every one of its six call sites was already behind WritesCanonical() and so
   was already dead whenever a notebook was linked. */
// review-store S1: "v2<TAB>writtenAt<TAB>owner<TAB>x<TAB>y<TAB>z<TAB>squadSid<TAB>factionName<TAB>worldId<TAB>posAt"; the old
// space-separated line is refused (it cannot be parsed back when an id has spaces) - the record file stays, the index entry is rebuilt on the next write.
bool ParseMetaLine(const std::string& line, Record* r)
{
    std::vector<std::string> f; size_t at = 0;
    while (at <= line.size()) { size_t t = line.find('\t', at); if (t == std::string::npos) { f.push_back(line.substr(at)); break; } f.push_back(line.substr(at, t - at)); at = t + 1; }
    /* P8b (design-save.md S1): v5 appends the payload's byte LENGTH and its CRC-32 to the line. The notebook
       writes v5 and validates it; this loader ACCEPTS v5 and ignores the two extra fields - it reads by field
       index and its only floor is 10, so nothing else here changes. Without this one line every v5 line the
       notebook writes would be refused here and that group would vanish from the game's index (design-save 1.3,
       "compatibility, stated rather than discovered"). Validating them on this side is owed, not built. */
    /* B10: v6 too - the notebook writes FORMAT 6 now (design-e46-store 3.5). This loader reads by
       field index with a floor of 10 and ignores the two appended fields, so nothing else changes;
       without this line every v6 line the notebook writes would be refused here and that group would
       vanish from this game's read-only bootstrap index. `owner` is read as found: a v5 line's role
       is a number in 0..2, which OwnerTranslateDecide treats as "a slot that is not mine" and so
       translates - the fail-safe direction - until the notebook has migrated the folder. */
    /* B12: v7 too - the notebook writes FORMAT 7 now (decision 52), which APPENDS `seq` as field 14.
       Without this name every v7 line the notebook writes would be refused here and that group would
       vanish from this game's read-only bootstrap index; and unlike the two v5 fields this one is READ,
       because seq is the only thing a queued write's conflict can be decided against. */
    if (f.size() < 10 || (f[0] != "v2" && f[0] != "v3" && f[0] != "v4" && f[0] != "v5" && f[0] != "v6"
                          && f[0] != "v7")) return false;
    r->gone = 0;   // decision 28: no gone entries exist; a v3 line from the superseded build is read as live
    /* B10-b (review-b10 M-1): THE OWNER FIELD IS PARSED BY THE SHARED PARSER, NOT BY atoi. kOwnerUnknown is
       4294967295 on a line, and std::atoi cannot hold it: under v100 it saturates to 2147483647, so a record
       whose writer was UNKNOWN read back as a real - and enormous - slot, and OwnerTranslateDecide answered
       "a different game wrote this" where the whole point of the unknown value is that it must answer
       "unknown". The parse now goes through coopstore::MetaOwnerFieldValid, the SAME call the notebook and
       the offline suite make, so the three programs cannot hold three ideas of one field; a field this build
       does not understand REFUSES the line (counted indexBadLines) rather than being read as slot 0, which is
       a real slot and would make some game the author of a record it never wrote. The u32 is kept in the
       `int owner` the record decoders hand out, where kOwnerUnknown reads back as -1 - deliberate, stated in
       storemeta.h, and the same cast the six StoreOwnerField() writers make. */
    unsigned int ownerField = coopstore::kOwnerUnknown;
    if (!coopstore::MetaOwnerFieldValid(f[2], &ownerField)) return false;
    r->writtenAt = _atoi64(f[1].c_str()); r->owner = (int)ownerField; r->x = (float)atof(f[3].c_str()); r->y = (float)atof(f[4].c_str()); r->z = (float)atof(f[5].c_str());
    r->squadSid = f[6]; r->factionName = f[7]; r->worldId = f[8]; r->posAt = _atoi64(f[9].c_str());
    if (!r->worldId.empty() && r->worldId[r->worldId.size() - 1] == '\r') r->worldId.erase(r->worldId.size() - 1);
    r->town = f.size() >= 11 ? f[10] : std::string(); if (!r->town.empty() && r->town[r->town.size() - 1] == '\r') r->town.erase(r->town.size() - 1);   /* v4 */
    /* B12 (decision 52): the notebook's sequence number, field 14 of a v7 line. Digits only and the whole
       field or the LINE is refused - a seq read short decides a replay conflict wrongly and silently,
       which is the one failure the sequence number exists to remove. A line below v7 leaves it at 0. */
    r->seq = 0;
    if (f[0] == "v7")
    {
        if (f.size() < 14) return false;
        std::string sq = f[13];
        while (!sq.empty() && (sq[sq.size() - 1] == '\r' || sq[sq.size() - 1] == '\n')) sq.erase(sq.size() - 1);
        if (sq.empty() || sq.size() > 20) return false;
        for (std::string::size_type i = 0; i < sq.size(); ++i)
        {
            if (sq[i] < '0' || sq[i] > '9') return false;
            r->seq = r->seq * 10 + (unsigned long long)(sq[i] - '0');
        }
    }
    /* field 15 of a v7 line: the group's home building key, optional (storemeta.h); a line without it reads as no home */
    r->home.clear();
    if (f[0] == "v7" && f.size() >= 15) { r->home = f[14]; while (!r->home.empty() && (r->home[r->home.size() - 1] == '\r' || r->home[r->home.size() - 1] == '\n')) r->home.erase(r->home.size() - 1); }
    return !r->worldId.empty();
}
/* ================= B12 (decision 52): THE OUTAGE QUEUE'S JOURNAL =================
   Decision 44 stopped this game writing boxes, doors and zone files while the notebook process is
   unreachable. Decision 52 keeps the player's move: the refused write is written down here and re-issued
   at the next link-up. The decisions - the conflict rule and the line's own format - are pure and live in
   src/common/queuejournal.h, swept offline; this is the file, the list and the counters.
   THE FILE is <world folder>\\queue.txt (W2b, decision 58: coop-store\\<world>\\queue.txt; the notebook's
   one-time migration moves an old coop-store\\queue-<world>.txt there) - BESIDE mirror-<pid>, never inside it,
   because mirror-<pid> is orphaned by the next run's new pid and so cannot hold anything that must survive a
   restart. Every entry in it belongs to the world whose folder holds it BY CONSTRUCTION: a different world is a
   different folder, so there is no world term to check inside a line.
   THE WHOLE FILE IS REWRITTEN on every change, through WriteFileBytes (temp + MoveFileEx). The queue is
   small - it holds one session's refused writes - and a rewrite cannot leave the file describing a state
   the list is not in, which an append could.
   MAIN THREAD ONLY: it reads g_records and rewrites a file. Every one of the three call sites is on the
   main thread already (the box drain, the door drain and ZoneSaveApply, which is main-thread by
   construction); an off-thread call is refused, counted and said rather than served. */
const char* const kQueueFamilyName[coopqueue::kQueueFamilyCount] = { "box", "door", "zone" };
std::vector<coopqueue::QueueEntry> g_queue;
long long g_queueQueued = 0, g_queueWriteFailed = 0, g_queueLoaded = 0, g_queueReplayed = 0;
long long g_queueDropNewerWriter = 0, g_queueDropUnknown = 0, g_queueDropBadEntry = 0;
long long g_queueOffThread = 0, g_queueKeyRefused = 0, g_queueSeqNoRecord = 0;
/* B12-c (review-b12). FIVE MORE OUTCOMES, EACH ITS OWN EVENT.
   dropBadPayload (M-4): an entry whose saved write could not be read back at the replay. It used to be
   counted as REPLAYED, which is a lost move printed as a written one.
   dropNotMineNow (M-5): the zone ladder was asked again at the replay - decision 40 wins over a stale
   queue - and another game holds that sector now.
   droppedFull (M-1): a write past the journal's cap. It was never queued, so it is OUTSIDE the identity.
   superseded (M-1): an entry replaced in place by a later one for the same key. It WAS queued and left
   without a verdict, so it IS inside the identity.
   seqZeroIgnored (H-1): an arriving RECORD whose seq field is 0 - the session peer always sends 0 and so
   does a notebook one build behind, and writing it in would reset this game's cached number to nothing. */
long long g_queueDropBadPayload = 0, g_queueDropNotMineNow = 0, g_queueDroppedFull = 0;
long long g_queueSuperseded = 0, g_queueSeqZeroIgnored = 0;
/* B12-b: the notebook's echo of the number it stamped on a record THIS GAME wrote. received is every echo
   that arrived; the next three are its outcomes and sum to it - applied (the key is in this game's index
   and took the number), unknownKey (no record here, counted and never created) and malformed. */
long long g_queueSeqEchoReceived = 0, g_queueSeqEchoApplied = 0, g_queueSeqEchoUnknownKey = 0;
long long g_queueSeqEchoMalformed = 0;
long long g_queueFamilyQueued[coopqueue::kQueueFamilyCount] = { 0, 0, 0 };
/* The zone road's two numbers, kept with the journal they feed rather than with the zone counters, so the
   three families' queue books are read in one place. */
long long g_zoneQueuedNoNotebook = 0, g_zoneQueueRefused = 0;
/* A replayed zone file whose MIRROR copy could not be written. Its own number rather than the zone road's
   zoneWriteFail, which is ZoneSaveApply's own exit and would read as a save having failed. */
long long g_queueZoneWriteFailed = 0;
/* ZoneWriteIsMine's answer to "was that refusal decision 44's one?", read by its ONE caller on the same
   thread in the same statement pair. It is a flag and not a return value because the function's bool is
   asked by name in several readouts and widening it would change every one of them. */
int g_zoneLastRefusedNoNotebook = 0;
std::string QueueFile() { return g_dirCanonical + "\\queue.txt"; }   /* W2b: inside the world folder - see THE FILE above */
int QueueSave()
{
    if (!g_indexLoaded) { ++g_writesHeldBeforeIndex; return 1; }   /* W2-f (review-w2 B): held in memory, written at QueueLoad */
    std::string all;
    for (std::vector<coopqueue::QueueEntry>::size_type i = 0; i < g_queue.size(); ++i)
    {
        std::string line;
        if (coopqueue::QueueLineFormat(g_queue[i], &line) == 0) continue;   /* refused at the door below - unreachable here, and a line that cannot be written is not guessed */
        all += line;
    }
    const std::vector<char> b(all.begin(), all.end());
    if (!WriteFileBytes(QueueFile(), b))
    {
        ++g_queueWriteFailed;
        /* B12-c (review-b12 M-3): THIS IS NOT A LOST MOVE and must not be said as one. The entries are in
           memory and will replay at this session's next link-up; what has been lost is only their survival
           of a restart of the game. The caller is told 1 for the same reason. */
        ErrorLog("[STORE] outage queue: could NOT write " + QueueFile() + " - the "
                 + N((long long)g_queue.size()) + " entry(ies) in it are QUEUED IN MEMORY ONLY. They will be"
                 " written for real at this session's next link-up, but they will not survive a restart of"
                 " the game until the journal file can be written (decision 52)");
        return 0;
    }
    return 1;
}
void QueueLoad()
{
    /* W2-f (review-w2 B): entries queued this session BEFORE the index was read are in memory only (QueueSave wrote
       nothing). They are kept: the file's entries load first (older - a previous session's), then each held entry
       joins them, and for a key whose family supersedes (door, zone) the held entry REPLACES the file's in place -
       exactly StoreQueueWriteImpl's supersede; the file entry it replaces counts superseded. Held entries were counted
       queued when they were queued and are not counted again. */
    std::vector<coopqueue::QueueEntry> held;
    held.swap(g_queue);
    std::vector<char> b;
    long long good = 0, bad = 0, heldSuperseding = 0;
    const bool haveFile = ReadFileBytes(QueueFile(), &b);   /* no journal is the ordinary case and is not an event */
    const std::string all = haveFile ? std::string(b.begin(), b.end()) : std::string();
    std::string::size_type at = 0;
    while (at < all.size())
    {
        const std::string::size_type nl = all.find('\n', at);
        const std::string line = (nl == std::string::npos) ? all.substr(at) : all.substr(at, nl - at);
        at = (nl == std::string::npos) ? all.size() : nl + 1;
        if (line.empty() || line == "\r") continue;
        coopqueue::QueueEntry e;
        if (coopqueue::QueueLineParse(line, &e) == 0) { ++g_queueDropBadEntry; ++bad; continue; }
        g_queue.push_back(e);
        ++g_queueLoaded; ++g_queueQueued; ++g_queueFamilyQueued[e.family]; ++good;
    }
    for (std::vector<coopqueue::QueueEntry>::size_type h = 0; h < held.size(); ++h)
    {
        bool replaced = false;
        if (coopqueue::QueueFamilySupersedes(held[h].family) != 0)
        {
            for (std::vector<coopqueue::QueueEntry>::size_type i = 0; i < g_queue.size(); ++i)
            {
                if (g_queue[i].family != held[h].family || g_queue[i].key != held[h].key) continue;
                coopqueue::QueueEntry m = held[h];
                if (g_queue[i].ownAhead != 0) m.ownAhead = g_queue[i].ownAhead;   /* a fact about the key, as at the write */
                g_queue[i] = m;
                ++g_queueSuperseded; ++heldSuperseding; replaced = true;
                break;
            }
        }
        if (!replaced) g_queue.push_back(held[h]);
    }
    if (haveFile || !held.empty())
        DebugLog("[STORE] outage queue: loaded " + N(good) + " entry(ies) from " + QueueFile() + " and dropped "
                 + N(bad) + " line(s) that could not be parsed; " + N((long long)held.size()) + " entry(ies) queued before"
                 " the index was read were kept (" + N(heldSuperseding) + " of them replaced the file's entry for the same"
                 " key). A loaded entry counts as QUEUED, so the readout's identity closes across the restart (decision 52).");
    if (bad != 0 || !held.empty()) QueueSave();   /* unparseable lines leave the file; held entries reach it */
}
int StoreQueueWriteImpl(int family, const std::string& recordKey, const std::vector<char>& payload)
{
    if (coopqueue::QueueFamilyValid(family) == 0) { ++g_queueKeyRefused; return 0; }
    if (!OnMainThread())
    {
        ++g_queueOffThread;
        ErrorLog("[STORE] outage queue: a " + std::string(kQueueFamilyName[family]) + " write for '"
                 + recordKey + "' was offered OFF THE MAIN THREAD and is refused - the journal reads the"
                 " record index and rewrites a file, and all three of its call sites are on the main"
                 " thread, so this is a defect and not a state (decision 52)");
        return 0;
    }
    if (!g_dirReady || recordKey.empty()) { ++g_queueKeyRefused; return 0; }
    coopqueue::QueueEntry e;
    e.family = family;
    e.key = recordKey;
    e.queuedAtUnix = (long long)time(0);
    e.payload = payload;
    e.seqSeen = 0;
    {
        /* THE SEQUENCE NUMBER AS IT STANDS NOW. This is the whole of the conflict rule's memory: at the
           replay the same key's seq is asked again, and equal means nobody wrote in between. B12-b is what
           makes it true for a key THIS GAME wrote earlier in the session: the notebook's RECORD_SEQ echo
           brought that number here at the write, so what is read below is current and not one behind. */
        std::map<std::string, Record>::const_iterator it = g_records.find(recordKey);
        if (it != g_records.end()) e.seqSeen = it->second.seq;
    }
    {
        std::string line;
        if (coopqueue::QueueLineFormat(e, &line) == 0)
        {
            ++g_queueKeyRefused;
            ErrorLog("[STORE] outage queue: the key '" + recordKey + "' cannot be written as a journal line"
                     " (it carries a tab or a newline) and the " + std::string(kQueueFamilyName[family])
                     + " write is NOT queued - that move is lost (decision 52)");
            return 0;
        }
    }
    /* B12-c (review-b12 M-1) THE SUPERSEDE. A zone entry is a whole saved FILE and a door entry a whole
       STATE, so only the newest one for a key can be right and the older one is replaced IN PLACE - it
       keeps its position in the file, so the order the refusals happened in is the order they replay in,
       and it keeps its ownAhead mark, which is a fact about this key and not about that payload. A BOX MOVE
       IS AN EVENT (remove eight plates, then add three) and the second does not describe the first, so
       every box entry is kept. The one it replaces WAS queued and leaves with no verdict, which is why it
       is counted: the identity would not close otherwise. */
    if (coopqueue::QueueFamilySupersedes(family) != 0)
    {
        for (std::vector<coopqueue::QueueEntry>::size_type i = 0; i < g_queue.size(); ++i)
        {
            if (g_queue[i].family != family || g_queue[i].key != recordKey) continue;
            e.ownAhead = g_queue[i].ownAhead;
            g_queue[i] = e;
            ++g_queueQueued; ++g_queueFamilyQueued[family]; ++g_queueSuperseded;
            DebugLog("[STORE] outage queue: the " + std::string(kQueueFamilyName[family]) + " write for '"
                     + recordKey + "' SUPERSEDES the one already queued for it (only the newest state of a "
                     + std::string(kQueueFamilyName[family]) + " can be right), " + N((long long)payload.size())
                     + " payload bytes, " + N((long long)g_queue.size()) + " entry(ies) waiting (decision 52)");
            QueueSave();
            return 1;
        }
    }
    /* B12-c (review-b12 M-1) THE CAP. The file is rewritten whole on every change and a zone payload is
       hex-doubled inside it, so an unbounded list turns a long outage into a growing stall on the main
       thread. Past either bound the write is REFUSED AND SAID: a silent drop is the one thing decision 52
       exists to remove, so the player is told that this move is the one that did not fit. */
    {
        unsigned int held = 0;
        for (std::vector<coopqueue::QueueEntry>::size_type i = 0; i < g_queue.size(); ++i)
            held += (unsigned int)g_queue[i].payload.size();
        if ((int)g_queue.size() >= coopqueue::kQueueMaxEntries
            || (unsigned long long)held + (unsigned long long)payload.size() > (unsigned long long)coopqueue::kQueueMaxBytes)
        {
            ++g_queueDroppedFull;
            ErrorLog("[STORE] outage queue is FULL and this " + std::string(kQueueFamilyName[family])
                     + " write for '" + recordKey + "' is LOST: " + N((long long)g_queue.size())
                     + " entry(ies) and " + N((long long)held) + " payload bytes are already waiting, and the"
                     " cap is " + N((long long)coopqueue::kQueueMaxEntries) + " entries / "
                     + N((long long)coopqueue::kQueueMaxBytes) + " bytes. The notebook has been away long"
                     " enough that this game cannot keep holding its refused writes (decision 52).");
            return 0;
        }
    }
    g_queue.push_back(e);
    ++g_queueQueued; ++g_queueFamilyQueued[family];
    DebugLog("[STORE] outage queue: the " + std::string(kQueueFamilyName[family]) + " write for '" + recordKey
             + "' is QUEUED (seqSeen=" + N((long long)e.seqSeen) + ", " + N((long long)payload.size())
             + " payload bytes, " + N((long long)g_queue.size()) + " entry(ies) waiting) - it is written for"
             " real when the notebook returns (decision 52)");
    /* B12-c (review-b12 M-3): THE ENTRY IS IN MEMORY, SO THIS SUCCEEDED. QueueSave's own failure is counted
       and said by QueueSave; it means "not until a restart", not "lost", and the caller's LOST text is for
       the three refusals above (off the main thread, an unwritable key, and the cap). */
    QueueSave();
    return 1;
}
/* MAIN THREAD (LoadIndex). An area record read from the world server's folder names the server's <id>.platoon file. The area-load
   swap serves a file named as the engine's own area file (<id>.zone) - the engine names the area it loads from the file's name - so
   the server's file is copied into this game's mirror under that name and the record points at the copy. A copy that fails leaves the
   record on the mirror name with no file there: the swap counts it missing and the engine loads its own save's area. */
long long g_zoneIndexCopied = 0, g_zoneIndexCopyFailed = 0;
bool ZoneIndexMirrorCopy(Record* r)
{
    const std::string from = r->file;
    r->file = MirrorFile(r->worldId);
    std::vector<char> bytes;
    const bool readOk = ReadFileBytes(from, &bytes);
    const bool ok = readOk && WriteFileBytes(r->file, bytes);
    if (ok) ++g_zoneIndexCopied; else ++g_zoneIndexCopyFailed;
    if (g_zoneIndexCopied + g_zoneIndexCopyFailed <= 8)
        DebugLog("[STORE] index: area record " + r->worldId + (ok ? " copied" : (readOk ? " NOT copied (the mirror write failed)" : " NOT copied (the world server's file could not be read)"))
                 + " from " + from + " to " + r->file + " (" + N((long long)bytes.size()) + " bytes) - the area-load swap serves the copy;"
                 + " zoneIndexCopied=" + N(g_zoneIndexCopied) + " zoneIndexCopyFailed=" + N(g_zoneIndexCopyFailed) + " (first 8 logged)");
    return ok;
}
void LoadIndex()
{
    /* W2-f (review-w2 B): set FIRST, so the journal merge below (QueueLoad -> QueueSave) and the held deleted-bits
       writes reach their files; before this line both only hold in memory. */
    g_indexLoaded = true;
    LoadBitsFiles();   /* decision 30 */
    for (std::set<std::string>::const_iterator it = g_bitsHeldBeforeIndex.begin(); it != g_bitsHeldBeforeIndex.end(); ++it)
        WriteBitsFile(*it);   /* W2-f: OR-merged with the file, as every bits write is */
    g_bitsHeldBeforeIndex.clear();
    /* B12 (decision 52): THE OUTAGE JOURNAL LOADS WHERE THE INDEX DOES, and for the same reason - both
       belong to a co-op world and this function is reached only through StoreArmWorldIndex (W2b: the install's
       host/client arm, StoreRoleLeftSingle and the store WELCOME). A lone game reads neither. */
    QueueLoad();
    U8FindData fd; std::string pat = g_dirCanonical + "\\*.meta";
    HANDLE h = U8FindFirstFile(pat.c_str(), &fd);
    if (h == INVALID_HANDLE_VALUE) return;
    g_publishSuppressed = true;   /* review-p5a MEDIUM-2: burst 1 - every .meta file is a first sighting */
    do
    {
        std::ifstream f(U8W((g_dirCanonical + "\\" + fd.cFileName).c_str()).c_str()); if (!f) continue;
        std::string line; if (!std::getline(f, line)) continue;
        Record r; if (!ParseMetaLine(line, &r)) { ++g_indexBadLines; continue; }
        if (DeletedBitTest(r.worldId)) { ++g_recvRefusedDeleted; continue; }   /* review-p4h M1 */
        NoteTownPeople(r.worldId, r.town);   /* decision 34 */
        NoteRecordHome(r.worldId, r.home);   /* the group's home building key (optional field 15) */
        if (IsZoneId(r.worldId) && !g_zoneOn) continue;   // review-p3h H1: zone records stay out of the index while the lever is off
        r.file = CanonicalFile(r.worldId);
        std::map<std::string, Record>::iterator it = g_records.find(r.worldId);
        if (it == g_records.end() || it->second.writtenAt < r.writtenAt)
        {
            /* the swap serves the engine's own area file name; a failed copy never replaces a record this game already holds */
            if (IsZoneId(r.worldId) && !ZoneIndexMirrorCopy(&r) && it != g_records.end()) continue;
            g_records[r.worldId] = r; ZoneSwapPublish(r.worldId); ++g_indexRecords;   /* Z1-b: the swap table follows every zone write */
        }
    } while (U8FindNextFile(h, &fd));
    ::FindClose(h);
    g_publishSuppressed = false;
    PublishPendingTowns();   /* review-p5a MEDIUM-2: once for the whole index, not once per note */
}
/* W2b (decision 58; design-worlds section 1) - THE ONE PLACE THE RECORD INDEX IS ARMED, FOR THIS GAME'S WORLD.
   Three callers: the install (co-op roles), StoreRoleLeftSingle, and the notebook's store WELCOME (main thread,
   before any record of that push is applied). While coop-store\ still holds the OLD single layout (loose world
   files the notebook has not yet moved into coop-store\<world>\ - it moves them at its own start, before it
   listens) the index is NOT read: it would read an empty world folder. The WELCOME retries it, by which time the
   notebook has moved them. The folders are created here and only here, together with the index read (P7i). */
std::vector<coopworld::DirEntry> ListStoreRootEntries(const std::string& root)
{
    std::vector<coopworld::DirEntry> out;
    U8FindData fd; HANDLE h = U8FindFirstFile((root + "\\*").c_str(), &fd);
    if (h == INVALID_HANDLE_VALUE) return out;
    do
    {
        const std::string n = fd.cFileName;
        if (n == "." || n == "..") continue;
        out.push_back(coopworld::DirEntry(n, (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0));
    } while (U8FindNextFile(h, &fd));
    ::FindClose(h);
    return out;
}
/* T-490: THE JOINED WORLDS' TOP FOLDER, beside the worlds top: storedir='s sibling "joined" when storedir= moves the worlds top, else
   <data folder>\joined, else <save root>\Shared Wastelands\joined; "" = none. */
std::string JoinedTopDir()
{
    const std::string cfgStore = ConfigStoreDir();
    if (!cfgStore.empty())
    {
        std::string d(cfgStore);
        while (!d.empty() && (d[d.size() - 1] == '\\' || d[d.size() - 1] == '/')) d.erase(d.size() - 1);
        const std::string::size_type cut = d.find_last_of("\\/");
        return cut == std::string::npos ? std::string() : d.substr(0, cut) + "\\" + swnames::kJoinedSub;
    }
    const std::string j = coopdata::JoinedDir(ConfigDataDir());
    if (!j.empty()) return j;
    const std::string saveRoot = SaveRootDefault();
    return saveRoot.empty() ? std::string() : saveRoot + "\\" + swnames::kSaveRootSub + "\\" + swnames::kJoinedSub;
}
bool StoreFileThere(const std::string& p) { return U8GetFileAttributes(p.c_str()) != INVALID_FILE_ATTRIBUTES; }
/* T-490: THE FOLDER THAT HOLDS THIS GAME'S DATA FOR (world, id) - coopworld::WorldDataDirDecide: the world's own folder when no id
   tells worlds apart or this computer runs that very world (its world.txt carries the id), else the joined folder. *ownDir = the
   world's own folder either way. */
std::string StoreDataDirFor(const std::string& world, const std::string& worldId, bool* joined, std::string* ownDir, bool* fellBack)
{
    const std::string own = coopworld::WorldDirIn(BaseDir(), world, fellBack);
    if (ownDir != 0) *ownDir = own;
    if (joined != 0) *joined = false;
    if (!coopworld::WorldIdOk(worldId)) return own;
    std::vector<char> b; std::string txt;
    if (ReadFileBytes(own + "\\world.txt", &b)) txt.assign(b.begin(), b.end());
    if (coopworld::WorldDataDirDecide(txt, worldId) != coopworld::kDataDirJoined) return own;
    const std::string j = coopworld::JoinedDirIn(JoinedTopDir(), world, worldId);
    if (j.empty()) return own;
    if (joined != 0) *joined = true;
    return j;
}
/* owner 429: A FOLDER'S FORMAT NUMBER (swformat) - read only. *found = its number (0 = no file). */
int StoreDataFolderFormat(const std::string& dir, int kind, unsigned int* found, std::string* why = 0)   /* why: an unreadable file's reason */
{
    const std::string p = dir + "\\" + swnames::kFormatFile;
    const bool exists = StoreFileThere(p);
    std::vector<char> b; std::string t;
    if (exists && ReadFileBytes(p, &b)) t.assign(b.begin(), b.end());
    const int rs = swformat::FormatParse(exists, t, kind, found, why);
    return swformat::FormatDecide(rs, *found, swformat::FolderFormatKnown(kind));
}
/* T-490 J0: the entries of one journal text (unparseable lines counted in *bad). */
std::vector<coopqueue::QueueEntry> QueueEntriesOf(const std::string& all, long long* bad)
{
    std::vector<coopqueue::QueueEntry> out;
    std::string::size_type at = 0;
    while (at < all.size())
    {
        const std::string::size_type nl = all.find('\n', at);
        const std::string line = (nl == std::string::npos) ? all.substr(at) : all.substr(at, nl - at);
        at = (nl == std::string::npos) ? all.size() : nl + 1;
        if (line.empty() || line == "\r") continue;
        coopqueue::QueueEntry e;
        if (coopqueue::QueueLineParse(line, &e) == 0) { ++*bad; continue; }
        out.push_back(e);
    }
    return out;
}
/* T-490 J0: THE OLD OUTAGE JOURNAL JOINS THE JOINED FOLDER'S. With no joined journal and no index read yet the old file is just moved.
   Otherwise its entries go FIRST and the joined journal's (on disk, or in memory once the index is read) after them
   (coopqueue::QueueMergeOlderFirst - replay is in file order, a newer door / zone entry superseding the older one in place), the
   result is written, and the old file goes to the Recycle Bin (deleted when the bin cannot take it). True = taken. MAIN THREAD. */
bool JoinedQueueTake(const std::string& oldPath)
{
    if (!g_indexLoaded && !StoreFileThere(QueueFile()))
    {
        if (U8MoveFileEx(oldPath.c_str(), QueueFile().c_str(), 0))
        {
            ++g_joinedQueueTaken;
            DebugLog("[STORE] T-490: the outage journal " + oldPath + " (from before joined folders) moved to " + QueueFile());
            return true;
        }
        if (g_joinedQueueLeft++ == 0)
            ErrorLog("[STORE] T-490: the outage journal " + oldPath + " could NOT be moved to " + QueueFile() + " (Windows error "
                     + N((long long)::GetLastError()) + ") - the joined folder is not converted; tried again at the next accepted WELCOME");
        return false;
    }
    std::vector<char> ob;
    if (!ReadFileBytes(oldPath, &ob))
    {
        if (g_joinedQueueLeft++ == 0)
            ErrorLog("[STORE] T-490: the outage journal " + oldPath + " could NOT be read - the joined folder is not converted; tried again at the next accepted WELCOME");
        return false;
    }
    long long bad = 0, sup = 0;
    const std::vector<coopqueue::QueueEntry> older = QueueEntriesOf(std::string(ob.begin(), ob.end()), &bad);
    std::vector<coopqueue::QueueEntry> newer;
    if (g_indexLoaded) newer = g_queue;
    else { std::vector<char> nb; if (ReadFileBytes(QueueFile(), &nb)) newer = QueueEntriesOf(std::string(nb.begin(), nb.end()), &bad); }
    const std::vector<coopqueue::QueueEntry> merged = coopqueue::QueueMergeOlderFirst(older, newer, &sup);
    if (g_indexLoaded)
    {
        g_queue = merged;
        for (size_t i = 0; i < older.size(); ++i) { ++g_queueLoaded; ++g_queueQueued; ++g_queueFamilyQueued[older[i].family]; }
        g_queueSuperseded += sup;
        QueueSave();   /* a failed write is said there; the entries stay in memory and replay this session */
    }
    else
    {
        std::string all;
        for (size_t i = 0; i < merged.size(); ++i) { std::string line; if (coopqueue::QueueLineFormat(merged[i], &line) != 0) all += line; }
        if (!WriteFileBytes(QueueFile(), std::vector<char>(all.begin(), all.end())))
        {
            if (g_joinedQueueLeft++ == 0)
                ErrorLog("[STORE] T-490: could NOT write the merged outage journal " + QueueFile() + " - the joined folder is not converted; tried again at the next accepted WELCOME");
            return false;
        }
    }
    std::string full = oldPath;
    { char fp[MAX_PATH * 2]; const DWORD got = U8GetFullPathName(oldPath.c_str(), (DWORD)sizeof fp, fp, 0); if (got > 0 && got < (DWORD)sizeof fp) full = fp; }
    std::vector<char> from(full.begin(), full.end()); from.push_back(0); from.push_back(0);
    SHFILEOPSTRUCTA op; ::ZeroMemory(&op, sizeof op);
    op.wFunc = FO_DELETE; op.pFrom = &from[0];
    op.fFlags = (FILEOP_FLAGS)(FOF_ALLOWUNDO | FOF_NOCONFIRMATION | FOF_SILENT | FOF_NOERRORUI);
    const bool binned = U8SHFileOperation(&op) == 0 && !op.fAnyOperationsAborted && !StoreFileThere(oldPath);
    const bool gone = binned || U8DeleteFile(oldPath.c_str()) != 0;
    ++g_joinedQueueTaken;
    DebugLog("[STORE] T-490: the outage journal " + oldPath + " (" + N((long long)older.size()) + " entries, from before joined folders) merged ahead of "
             + QueueFile() + "'s " + N((long long)newer.size()) + " (" + N(sup) + " superseded, " + N(bad) + " unreadable line(s) dropped); the old file "
             + (binned ? std::string("went to the Recycle Bin") : gone ? std::string("was deleted (the Recycle Bin did not take it)")
                       : std::string("could NOT be removed - it would be merged again, so this session takes no more from it")));
    return true;
}
/* owner 429 / T-490: A JOINED WORLD'S FOLDER, converted to this build's format (a newer one was refused at the WELCOME). Step 0 -> 1:
   world.txt names the world (from the WELCOME), and the outage journal its same-name world folder holds from before joined folders
   joins this folder's (JoinedQueueTake) when that folder is no world this computer runs and the world was upgraded
   (coopworld::JoinedQueueTakeDecide); the journal of a world this computer runs stays with it, logged. format.txt is written last,
   and only once the journal was taken or there was none to take - so a failed take is tried again at the next accepted WELCOME
   (JoinedFolderRetry). MAIN THREAD. */
void ConvertJoinedFolder(unsigned int from)
{
    static std::string s_taken;   /* an old journal merged this session but not removable is never merged twice */
    const std::vector<unsigned int> steps = swformat::FormatSteps(from, swformat::kJoinedFolderFormat);
    for (size_t i = 0; i < steps.size(); ++i)
    {
        if (steps[i] != 0) continue;
        const std::string wt = g_dirCanonical + "\\world.txt";
        if (!StoreFileThere(wt))
        {
            const std::string t = coopworld::WorldTxtFormatWithId(coopworld::WorldOrDefault(ConfigWorldKey(), 0), coopworld::WorldIdCreated(HeldWorldId()),
                                                                  HeldWorldId(), HeldWorldUpgraded());
            const std::vector<char> b(t.begin(), t.end());
            if (!WriteFileBytes(wt, b, true)) { ErrorLog("[STORE] T-490: could not write " + wt + " - the joined folder is converted again at the next accepted WELCOME"); return; }
        }
        std::string own;
        StoreDataDirFor(ConfigWorldKey(), HeldWorldId(), 0, &own, 0);
        const std::string oldQ = own + "\\queue.txt";
        const bool ownTxt = StoreFileThere(own + "\\world.txt"), ownQ = StoreFileThere(oldQ) && s_taken != oldQ;
        if (coopworld::JoinedQueueTakeDecide(ownTxt, ownQ, HeldWorldUpgraded()))
        {
            if (!JoinedQueueTake(oldQ)) return;   /* format.txt stays unwritten */
            if (StoreFileThere(oldQ)) s_taken = oldQ;
        }
        else if (ownQ)
        {
            ++g_joinedQueueLeft;
            DebugLog("[STORE] T-490: " + oldQ + " is left where it is: " + (ownTxt ? std::string("that folder is a world this computer runs, and the journal cannot be split between the two worlds")
                                                                              : std::string("this world was born with its id, so the journal is not its")));
        }
    }
    const std::string t = swformat::FormatText(swformat::kKindJoined, swformat::kJoinedFolderFormat);
    const std::vector<char> b(t.begin(), t.end());
    if (WriteFileBytes(g_dirCanonical + "\\" + swnames::kFormatFile, b, true))
    {
        ++g_formatConverted;
        DebugLog("[STORE] owner 429: joined folder " + g_dirCanonical + " converted from format " + N((long long)from) + " to " + N((long long)swformat::kJoinedFolderFormat));
    }
    else ErrorLog("[STORE] owner 429: could not write " + g_dirCanonical + "\\" + swnames::kFormatFile + " - converted again at the next accepted WELCOME");
}
/* T-490: AT EACH ACCEPTED WELCOME after the index read, a joined folder still without format.txt (its conversion failed) is tried again. */
void JoinedFolderRetry()
{
    if (!g_indexLoaded || !g_dirJoined || g_storeWrongWorld) return;
    unsigned int found = 0;
    if (StoreDataFolderFormat(g_dirCanonical, swformat::kKindJoined, &found) == swformat::kFormatConvert) ConvertJoinedFolder(found);
}
void StoreArmWorldIndex(const char* why)
{
    if (!g_dirReady || g_indexLoaded) return;
    const std::string w = why ? why : "?";
    SetStoreDirsFor(ConfigWorldKey(), g_linkWorldId);
    /* W3 (decisions 58/59) / W3-f (review-w3 item 6, M4 - THE HOST FOLLOWS TOO): EVERY CO-OP GAME READS ITS INDEX ONLY AT THE
       NOTEBOOK'S WELCOME, which names the world it follows (it may adopt one its shared_wastelands.cfg does not name). Read at
       install (or at a panel's single -> co-op edge) it would have opened its cfg world's folder first and could then only
       refuse the link. This is the state the W2b loose-layout deferral below already leaves: folders named, nothing
       created, nothing read. Counted indexReadSkipped; indexReadAt's install and roleLeftSingle slots stay 0. */
    if (w != "storeLink")
    {
        ++g_indexReadSkipped;
        DebugLog("[STORE] W3-f: role=" + std::string(ConfigRoleName()) + " - the record index is not read here (" + w + "); it is"
                 " read when the notebook's WELCOME has named the world this game follows.");
        return;
    }
    /* W2-f (review-w2 A): the loose old layout defers ONLY the install and roleLeftSingle reads. At the notebook's WELCOME
       it never does: on the notebook's own PC the notebook migrated before it listened, and on another PC the loose
       files are that PC's stale leftovers, which must not keep this game from its world forever. (W3-f: those two reads
       no longer happen at all - the skip above returns first - so the deferral branch below is not reached today.) */
    const bool looseLayout = coopworld::NeedsMigration(ListStoreRootEntries(BaseDir()), g_dirWorld);
    if (looseLayout && w == "storeLink")
        DebugLog("[STORE] W2-f: " + BaseDir() + " still has old-layout world files loose in it, but the notebook has linked -"
                 " reading world '" + g_dirWorld + "' anyway (the notebook migrates before it listens; loose files here are"
                 " this computer's leftovers).");
    if (looseLayout && w != "storeLink")
    {
        ++g_storeLooseDeferred;
        ErrorLog("[STORE] this computer's notebook folder has not been moved into world '" + g_dirWorld + "' yet - it is"
                 " moved when the notebook starts; the record index is read when the notebook links (" + w + ").");
        return;
    }
    EnsureStoreDirs();
    if (g_dirJoined)
    {
        unsigned int found = 0;
        if (StoreDataFolderFormat(g_dirCanonical, swformat::kKindJoined, &found) == swformat::kFormatConvert) ConvertJoinedFolder(found);
    }
    g_indexWorldId = g_linkWorldId; g_indexWorldUpgraded = g_linkWorldIdUpgraded;   /* T-490: the world whose records, mirror and queue this game now holds */
    LoadIndex();
    const int k = (w == "install") ? 0 : (w == "roleLeftSingle") ? 1 : 2;
    ++g_indexReadAt[k];
    DebugLog("[STORE] W2b: read the notebook record index of world '" + g_dirWorld + "' from " + g_dirCanonical
             + " (" + w + ", indexRecords=" + N(g_indexRecords) + ").");
}

std::string WorldIdOf(void* platoon)
{
    std::map<void*, std::string>::const_iterator it = g_bind.find(platoon);
    if (it != g_bind.end()) return it->second;
    std::string sid;
    if (!PlatoonSidPod(platoon, &sid)) { ++g_faults; if (++g_faultSid == 1) ErrorLog("[STORE] Q12 fault: getPlatoonStringID faulted for platoon " + P(platoon)); return std::string(); }
    return sid;
}
// ---- E4 (review-p5d CRASH-1 / review-p5f CRASH-1): THE MAIN-THREAD OUTBOX ------------------------------------------
// The three senders below (SendRecordAny, SendGoneAny, SendBitsAny) are reached from detours that carry no thread guard:
// detour_gdcSave (:997), detour_deactivate (:576/:577) and detour_destroyPlatoon (:837/:838). Every one of them ends in
// LinkUp() and then g_link->Send - TWO separate dereferences of a pointer the MAIN thread deletes in SetStoreServer - and
// two of them read a main-thread-only container on the way there: SendBitsAny's g_deletedBits[faction] is a std::map
// operator[], i.e. an INSERT into a map the main thread iterates at the link-up push, and SendRecordAny's payload encoder
// (net::EncodeRecordPayload) calls back into RecordTownOf, which reads g_records. So off the main thread NOTHING shared is
// touched at all: the sender's INPUTS are copied into this queue and the whole send - map lookup, payload build, transmit -
// happens on the tick, on the main thread. This is the shape DeletedBitSet / BitsDrainTick already use for the bitmap.
const unsigned int kStoreOutBits = 0xFFFFFFF0u;     // a queue-only type: `fac` names the faction whose bitmap to send
const unsigned int kStoreOutRecord = 0xFFFFFFF1u;   // a queue-only type: the record's arguments, encoded on the drain
