void OutboxLockInit() { if (!g_outboxLockInit) { ::InitializeCriticalSection(&g_outboxLock); g_outboxLockInit = true; } }   /* review-p4t CRASH: created eagerly in InstallStore, never lazily from a worker */
bool OutboxPush(const StoreOut& e)
{
    if (!g_outboxLockInit) return false;   // no lock yet means InstallStore has not run, and no detour is installed either
    bool full = false;
    const size_t bytes = OutEntryBytes(e);
    ::EnterCriticalSection(&g_outboxLock);
    /* F189's give-up rule, on BOTH axes (review-p5g MEDIUM-3): a game that runs unlinked for hours must not grow this queue
       without bound in entries OR in memory. A drop here is the cap's drop and nothing else's - the drain no longer drops. */
    if (g_storeOutbox.size() >= kOutboxMaxEntries || g_outboxBytes + bytes > kOutboxMaxBytes) full = true;
    else { g_storeOutbox.push_back(e); g_outboxBytes += bytes; }
    ::LeaveCriticalSection(&g_outboxLock);
    if (full) ::InterlockedIncrement64(&g_outboxDroppedCap); else ::InterlockedIncrement64(&g_outboxQueued);
    return !full;
}
