// PROBE-START: P113 (lever) - p113squad: the store builds a sleeping squad near the player from a record (CreateUnknownSquad, the
// T729 path), reloads its container once as the wake hook does (LoadPod), waits for the engine to wake it, then the engine's own
// Faction::removeSquad (through the hooked entry, as an engine destroy is seen) removes it - awake, or after the engine's sleep
// pair (mode sleep) - and the lever waits until P113 has seen that container's records destroyed. TEST-ONLY. [P113L] lines.
namespace coop {
typedef void (*P113DestroyFn)(void* faction, void* platoon);
int P113DestroyPod(void* faction, void* platoon)
{
    if (kDestroyPlatoonRva == 0) return 0;
    __try { ((P113DestroyFn)(Base() + kDestroyPlatoonRva))(faction, platoon); return 1; } __except (EXCEPTION_EXECUTE_HANDLER) { return -1; }
}
struct P113Lever { int on; int cycles; int cycle; int mode; int phase; void* plat; void* fac; void* cont; std::string wid; std::string src; DWORD t0; DWORD tWake;
                   int woke, destroyed, freedTotal, notWoken, failed; long long secondAtStart; };
P113Lever g_p113Lv = { 0, 0, 0, 2, 0, 0, 0, 0, std::string(), std::string(), 0, 0, 0, 0, 0, 0, 0, 0 };
const char* P113ModeWord(int m) { return m == 0 ? "awake" : (m == 1 ? "sleep" : "alt"); }
std::string P113PickSource(const std::string& want, std::string* why)
{
    for (std::map<std::string, Record>::const_iterator it = g_records.begin(); it != g_records.end(); ++it)
    {
        const Record& r = it->second;
        if (!want.empty() && it->first != want) continue;
        if (IsZoneId(it->first) || r.gone || r.file.empty() || r.squadSid.empty() || r.factionName.empty()) continue;
        if (U8GetFileAttributes(r.file.c_str()) == INVALID_FILE_ATTRIBUTES) continue;
        if (!Plaus(coop::GameWorldPtr()) || !Plaus(coop::GameWorldPtr()->factionDirectory)) { *why = "no world"; return std::string(); }
        Faction* f = FindFactionByKey(r.factionName);
        if (!Plaus(f) || IsPlayerFaction(f) || IsPeerFaction(f)) continue;
        if (!Plaus(coop::GameWorldPtr()->gamedata.getData(r.squadSid))) continue;
        return it->first;
    }
    *why = want.empty() ? "no record here can build a squad (file, faction, template)" : "that record cannot build a squad here";
    return std::string();
}
std::string P113SquadLever(const std::string& args)
{
    std::istringstream is(args); std::string a; is >> a;
    if (a == "report") { DebugLog(P113ReportLine()); DebugLog("[P113L] state on=" + N((long long)g_p113Lv.on) + " cycle=" + N((long long)g_p113Lv.cycle) + "/" + N((long long)g_p113Lv.cycles) + " phase=" + N((long long)g_p113Lv.phase) + " woke=" + N((long long)g_p113Lv.woke) + " destroyed=" + N((long long)g_p113Lv.destroyed) + " freed=" + N((long long)g_p113Lv.freedTotal) + " notWoken=" + N((long long)g_p113Lv.notWoken) + " failed=" + N((long long)g_p113Lv.failed)); return "ok p113squad report"; }
    if (a == "stop") { g_p113Lv.on = 0; ::InterlockedExchange(&g_p113Verbose, 0); g_p113WatchPlat = 0; g_p113WatchC = 0; DebugLog("[P113L] stopped at cycle " + N((long long)g_p113Lv.cycle)); return "ok p113squad stop"; }
    const int cycles = atoi(a.c_str());
    std::string m, src; is >> m >> src;
    if (cycles < 1 || cycles > 50 || (!m.empty() && m != "awake" && m != "sleep" && m != "alt"))
    { DebugLog("[cmd] usage: p113squad <cycles 1..50> [awake|sleep|alt] [sourceWorldId] | p113squad report | p113squad stop"); return "error p113squad usage"; }
    if (g_p113Lv.on) return "error p113squad already running";
    if (!g_dirReady || EngineWritesBlocked()) return "error p113squad no world/store";
    if (orig_p113GdDtor == 0) return "error p113squad probe P113 hook not installed";
    std::string why; const std::string pick = P113PickSource(src, &why);
    if (pick.empty()) { DebugLog("[P113L] refused: " + why); return "error p113squad " + why; }
    g_p113Lv.on = 1; g_p113Lv.cycles = cycles; g_p113Lv.cycle = 0; g_p113Lv.mode = m == "awake" ? 0 : (m == "sleep" ? 1 : 2); g_p113Lv.phase = 1; g_p113Lv.src = pick;
    g_p113Lv.woke = g_p113Lv.destroyed = g_p113Lv.freedTotal = g_p113Lv.notWoken = g_p113Lv.failed = 0; g_p113Lv.secondAtStart = g_p113Second; ::InterlockedExchange(&g_p113Verbose, 1);
    DebugLog("[P113L] start cycles=" + N((long long)cycles) + " mode=" + P113ModeWord(g_p113Lv.mode) + " source='" + pick + "' squad='" + g_records[pick].squadSid + "' faction='" + g_records[pick].factionName + "'");
    return "ok p113squad started";
}
void P113LeverFinishCycle(const char* how)
{
    const long freed = ::InterlockedExchange(&g_p113WatchFreed, 0);
    g_p113Lv.freedTotal += (int)freed;
    DebugLog("[P113L] cycle " + N((long long)g_p113Lv.cycle) + "/" + N((long long)g_p113Lv.cycles) + " " + how + " wid=" + g_p113Lv.wid + " platoon=" + P(g_p113Lv.plat) + " container=" + P(g_p113Lv.cont)
             + " freedRecords=" + N((long long)freed) + " SECOND(total)=" + N(g_p113Second) + " sharedHead(total)=" + N(g_p113Shared));
    g_p113WatchPlat = 0; g_p113WatchC = 0; g_p113Lv.plat = 0; g_p113Lv.cont = 0;
    g_p113Lv.phase = g_p113Lv.cycle >= g_p113Lv.cycles ? 0 : 1;
    if (g_p113Lv.phase == 0)
    {
        g_p113Lv.on = 0; ::InterlockedExchange(&g_p113Verbose, 0);
        DebugLog("[P113L] DONE cycles=" + N((long long)g_p113Lv.cycle) + " woke=" + N((long long)g_p113Lv.woke) + " notWoken=" + N((long long)g_p113Lv.notWoken) + " destroyed=" + N((long long)g_p113Lv.destroyed)
                 + " failed=" + N((long long)g_p113Lv.failed) + " freedRecords=" + N((long long)g_p113Lv.freedTotal) + " SECOND(this run)=" + N(g_p113Second - g_p113Lv.secondAtStart));
        DebugLog(P113ReportLine());
    }
}
/* 1 Hz from StoreTick (main thread). Each phase waits on a state it can see, with a ceiling. */
void P113LeverTick()
{
    if (!g_p113Lv.on) return;
    if (EngineWritesBlocked()) return;   /* a load or a teardown: wait */
    const DWORD now = ::GetTickCount();
    P113Lever& L = g_p113Lv;
    if (L.phase == 1)
    {
        ++L.cycle;
        std::map<std::string, Record>::const_iterator it = g_records.find(L.src);
        ::Character* ref = coop::GetTarget();
        if (it == g_records.end() || !Plaus(ref)) { ++L.failed; DebugLog(std::string("[P113L] cycle ") + N((long long)L.cycle) + " not started: " + (it == g_records.end() ? "source record gone" : "no reference character (GetTarget)")); P113LeverFinishCycle("SKIPPED"); return; }
        Record t = it->second;
        const Ogre::Vector3 pos = ref->worldPosition();
        const float ang = 0.7f * (float)L.cycle;
        t.x = pos.x + 25.0f * cosf(ang); t.y = pos.y; t.z = pos.z + 25.0f * sinf(ang); t.gone = 0;
        t.worldId = "p113t-" + N((long long)L.cycle) + "-" + N((long long)now);
        L.wid = t.worldId;
        if (!CreateUnknownSquad(t)) { ++L.failed; P113LeverFinishCycle("CREATE FAILED (see [STORE] CREATE lines)"); return; }
        std::map<std::string, void*>::const_iterator b = g_byWorldId.find(t.worldId);
        L.plat = b != g_byWorldId.end() ? b->second : 0;
        Pod q; if (L.plat == 0 || !ReadPod(L.plat, &q) || !Plaus(q.unloadedContainer)) { ++L.failed; P113LeverFinishCycle("CREATED but no platoon/container found"); return; }
        L.fac = q.faction; L.cont = q.unloadedContainer; g_p113WatchC = L.cont; ::InterlockedExchange(&g_p113WatchFreed, 0); ::InterlockedExchange(&g_p113WatchWoke, 0); g_p113WatchPlat = L.plat;
        const int mode = L.mode == 2 ? (L.cycle % 2 == 1 ? 0 : 1) : L.mode;
        L.phase = 2; L.t0 = now;
        DebugLog("[P113L] cycle " + N((long long)L.cycle) + " CREATED wid=" + t.worldId + " platoon=" + P(L.plat) + " container=" + P(L.cont) + " at " + F1(t.x) + "," + F1(t.y) + "," + F1(t.z) + " destroy=" + (mode == 0 ? "awake" : "after-sleep"));
        return;
    }
    if (L.phase == 2)
    {
        /* the wake hook's reload, done once while it sleeps (detour_activate runs the same LoadPod just before the original wake) */
        std::map<std::string, Record>::const_iterator it = g_records.find(L.src);
        const std::string modName;
        const int ld = (it != g_records.end() && !g_p113WatchWoke) ? LoadPod(L.cont, &it->second.file, &modName) : -3;
        DebugLog("[P113L] cycle " + N((long long)L.cycle) + " reload load=" + N((long long)ld) + (g_p113WatchWoke ? " (already awake - skipped)" : ""));
        L.phase = 3; L.t0 = now; return;
    }
    if (L.phase == 3)
    {
        if (g_p113WatchWoke) { ++L.woke; L.tWake = now; L.phase = 4; DebugLog("[P113L] cycle " + N((long long)L.cycle) + " WOKE after " + F1((now - L.t0) / 1000.0f) + " s"); return; }
        if (now - L.t0 > 60000) { ++L.notWoken; L.phase = 5; DebugLog("[P113L] cycle " + N((long long)L.cycle) + " NOT WOKEN in 60 s - destroyed asleep"); }
        else return;
    }
    if (L.phase == 4) { if (now - L.tWake < 3000) return; L.phase = 5; }   /* a few ticks awake, as T729's squad was */
    if (L.phase == 5)
    {
        const int mode = L.mode == 2 ? (L.cycle % 2 == 1 ? 0 : 1) : L.mode;
        Pod q; if (!ReadPod(L.plat, &q) || !Plaus(q.faction)) { ++L.failed; P113LeverFinishCycle("platoon unreadable before the destroy"); return; }
        void* target = L.plat; const char* how = "destroyed asleep";
        if (Plaus(q.active))
        {
            if (mode == 1)
            {
                if (StoreRetireLocalCopy(L.plat) != 1) { ++L.failed; P113LeverFinishCycle("engine sleep pair failed"); return; }
                void* sl = FindSleepingPlatoonImpl((Faction*)q.faction, L.wid); if (sl != 0) target = sl;
                how = "put to sleep by the engine pair, then destroyed";
            }
            else how = "destroyed awake";
        }
        g_p113WatchPlat = 0;
        const int rc = P113DestroyPod(q.faction, target);
        if (rc != 1) { ++L.failed; P113LeverFinishCycle(rc < 0 ? "Faction::removeSquad FAULTED" : "no destroy address"); return; }
        ++L.destroyed; L.phase = 6; L.t0 = now;
        DebugLog("[P113L] cycle " + N((long long)L.cycle) + " " + how + " (Faction::removeSquad through the hooked entry) platoon=" + P(target));
        return;
    }
    if (L.phase == 6)
    {
        /* the platoon is freed later in the frame loop and its container's records reach the kill list after that: wait for P113 to
           see them destroyed (and two more ticks for any second destroy), ceiling 15 s */
        static DWORD seen = 0;
        if (g_p113WatchFreed > 0 && seen == 0) seen = now;
        if ((seen != 0 && now - seen >= 2000) || now - L.t0 > 15000) { seen = 0; P113LeverFinishCycle(g_p113WatchFreed > 0 ? "DONE" : "DONE (no record of its container destroyed within 15 s)"); }
        return;
    }
}
} // namespace coop
// PROBE-END: P113 (lever)
